class StageScreen extends StatelessWidget {
  final String stageId;
  const StageScreen({super.key, required this.stageId});
  @override Widget build(BuildContext context) {
    if (stageId == 'kg1' || stageId == 'kg2') return KindergartenStageScreenV3(stageId: stageId);
    if (stageId == 'prep') return const KindergartenTestsScreen();
    final grade = stageId == 'g2' ? 2 : stageId == 'g3' ? 3 : 1;
    final title = stageId == 'g2' ? 'الصف الثاني' : stageId == 'g3' ? 'الصف الثالث' : 'الصف الأول';
    final cards = <Widget>[
      _StageButton('العربية','منهج العربية المناسب للمرحلة',Icons.menu_book_rounded,const Color(0xFF7652FF),ArabicCurriculumScreenV16(grade:grade),'📚 خطوة جديدة في القراءة!'),
      if (grade >= 2) _StageButton('قواعد اللغة العربية','القواعد والتراكيب',Icons.spellcheck_rounded,const Color(0xFFE94F9B),const ArabicGrammarScreenV12(),'📝 هيا نكتشف قواعد العربية!'),
      _StageButton('الرياضيات','جمع وطرح وقيمة مكانية ومهارات أخرى',Icons.calculate_rounded,const Color(0xFF18A7E8),MathCurriculumScreenV15(grade:grade),'🧮 عقل رياضي رائع!'),
      _StageButton('جدول الضرب','حسب المرحلة',Icons.close_rounded,const Color(0xFF16B878),const MultiplicationScreenV13(),'✖️ لنصبح أبطال جدول الضرب!'),
      _StageButton('الإنجليزية','قراءة وكتابة وتعلم تدريجي',Icons.language_rounded,const Color(0xFFFF8A3D),EnglishHomeScreen(stageId:stageId),'🇬🇧 Great!'),
      _StageButton('الكتابة','كلمات وجمل وتدريب كتابي',Icons.edit_note_rounded,const Color(0xFF8E5CF6),WritingScreen(stageId:stageId),'✍️ اكتب بنفسك!'),
      _StageButton('الألعاب والقصص','نشاطات وتحديات مرتبطة بالتعلم',Icons.sports_esports_rounded,const Color(0xFFFFB300),const GamesScreenV11(),'🏆 تحدٍ جديد!'),
    ];
    return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(title)),body:ListView(padding:const EdgeInsets.all(16),children:[App3DCard(onTap:()=>AppFeedback.show('🌟 $title — أنت تستطيع!'),child:Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:LinearGradient(colors:[Theme.of(context).colorScheme.primaryContainer,Theme.of(context).colorScheme.tertiaryContainer]),borderRadius:BorderRadius.circular(24)),child:Text(title,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900)))),const SizedBox(height:18),...cards])));
  }
}
class _StageButton extends StatelessWidget { final String title,subtitle,message; final IconData icon; final Color color; final Widget page; const _StageButton(this.title,this.subtitle,this.icon,this.color,this.page,this.message); @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:12),child:App3DCard(onTap:(){AppFeedback.show(message);Navigator.push(context,MaterialPageRoute(builder:(_)=>page));},encouragement:message,child:Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:LinearGradient(colors:[color,color.withValues(alpha:.68)]),borderRadius:BorderRadius.circular(22)),child:Row(children:[Icon(icon,color:Colors.white,size:40),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w900)),Text(subtitle,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w600))])),const Icon(Icons.arrow_back_ios_new_rounded,color:Colors.white)])))); }

