}
class _TestButton extends StatelessWidget { final String title,subtitle; final IconData icon; final List<Color> colors; final Widget page; const _TestButton(this.title,this.subtitle,this.icon,this.colors,this.page); @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:12),child:App3DCard(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>page)),encouragement:'✨ هيا نبدأ!',child:Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:LinearGradient(colors:colors),borderRadius:BorderRadius.circular(22)),child:Row(children:[Icon(icon,color:Colors.white,size:40),const SizedBox(width:12),Expanded(child:Text('$title\n$subtitle',style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w900))),const Icon(Icons.arrow_back_ios_new_rounded,color:Colors.white)])))); }
class _PrepLetterTest extends StatefulWidget{const _PrepLetterTest();@override State<_PrepLetterTest> createState()=>_PrepLetterTestState();}
class _PrepLetterTestState extends State<_PrepLetterTest>{int i=0;final qs=const[('اختر الحرف: ب',['أ','ب','ت'],'ب'),('اختر الحرف: م',['ن','م','ل'],'م'),('ما نتيجة د + و؟',['دو','دا','دي'],'دو'),('ما نتيجة ن + ا؟',['نا','نو','ني'],'نا'),('ما نتيجة ب + ا؟',['با','بو','بي'],'با')];@override Widget build(BuildContext c){final q=qs[i%qs.length];return _QuestionPage('اختبار الحروف',q.$1,q.$2,q.$3,()=>setState(()=>i++));}}
class _PrepNumberTest extends StatefulWidget{const _PrepNumberTest();@override State<_PrepNumberTest> createState()=>_PrepNumberTestState();}
class _PrepNumberTestState extends State<_PrepNumberTest>{int i=1;@override Widget build(BuildContext c){final t=i~/10,o=i%10;final choices=i<10?['$i','${i==9?1:i+1}','${i==1?3:i-1}']:['الآحاد: $o','العشرات: $t','العدد كاملًا'];final correct=i<10?'$i':(o>0?'الآحاد: $o':'العشرات: $t');return _QuestionPage('اختبار الأرقام',i<10?'اختر الرقم $i':'في العدد $i اختر قيمة الآحاد أو العشرات',choices,correct,()=>setState(()=>i=i==50?1:i+1));}}
