class _PrepColorTest extends StatefulWidget{const _PrepColorTest();@override State<_PrepColorTest> createState()=>_PrepColorTestState();}
class _PrepColorTestState extends State<_PrepColorTest>{int i=0;final qs=[('اختر اللون الأحمر',['أحمر','أزرق','أخضر'],'أحمر'),('اختر اللون الأخضر',['أصفر','أخضر','بنفسجي'],'أخضر'),('اختر اللون الأزرق',['أزرق','وردي','برتقالي'],'أزرق'),('اختر اللون الأبيض',['أسود','أبيض','بني'],'أبيض'),('اختر اللون البنفسجي',['بنفسجي','تركوازي','رمادي'],'بنفسجي')];@override Widget build(BuildContext c){final q=qs[i%qs.length];return _QuestionPage('اختبار الألوان',q.$1,q.$2,q.$3,()=>setState(()=>i++));}}
class _QuestionPage extends StatelessWidget{final String title,question,correct;final List<String> choices;final VoidCallback onNext;const _QuestionPage(this.title,this.question,this.choices,this.correct,this.onNext);@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(title)),body:ListView(padding:const EdgeInsets.all(18),children:[App3DCard(onTap:(){},child:Container(padding:const EdgeInsets.all(22),decoration:const BoxDecoration(gradient:LinearGradient(colors:[Color(0xFF8E5CF6),Color(0xFF18A7E8)]),borderRadius:BorderRadius.all(Radius.circular(24))),child:Text(question,textAlign:TextAlign.center,style:const TextStyle(color:Colors.white,fontSize:24,fontWeight:FontWeight.w900))),const SizedBox(height:18),for(final choice in choices)Padding(padding:const EdgeInsets.only(bottom:10),child:App3DCard(onTap:(){if(choice==correct){AppFeedback.show('🎉 أحسنت! إجابة صحيحة');onNext();}else{AppFeedback.show('💛 حاول مرة أخرى!');}},child:Container(padding:const EdgeInsets.symmetric(vertical:16),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF16B878),Color(0xFF18A7E8)]),borderRadius:BorderRadius.circular(18)),child:Center(child:Text(choice,style:const TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w900))))))])));}}
